{
  "items": [
    {
      "title": "The Political Situation in West Berlin (Young People), 1955",
      "url_or_doi": "https://doi.org/10.4232/1.0589",
      "justification": "Highly relevant historical survey dataset archived by GESIS (Study ZA0589). Conducted in January 1955 by DIVO Frankfurt for the United States Information Agency (USIA), it contains interviews with 313 young people aged 14–24 living in West Berlin. The survey examines young people's political attitudes, perceptions of economic development, and comparisons between East and West Berlin. This is one of the strongest directly relevant datasets for studying youth experiences and political perspectives in 1950s Berlin."
    },
    {
      "title": "The Political Situation in West Berlin (Young People from East Germany), 1955",
      "url_or_doi": "https://doi.org/10.4232/1.0590",
      "justification": "GESIS historical survey dataset (Study ZA0590) concerning young people from East Germany and their perspectives on the political situation in West Berlin. It is associated with the January 1955 survey of West Berlin youth (ZA0589). Particularly valuable for investigating East–West differences, youth migration, and Cold War political attitudes. The paired surveys offer opportunities for comparative research, although the precise sample characteristics and available files should be checked in the archive."
    },
    {
      "title": "European USIA Report Collection: Attitudes of East German Youth During the 1951 Berlin Youth Festival",
      "url_or_doi": "https://ropercenter.cornell.edu/european-usia-report-collection",
      "justification": "Historical public opinion research collection maintained by the Roper Center for Public Opinion Research at Cornell University. It includes a series of 1951 reports examining attitudes among East German youth during the Berlin Youth Festival. One identified report, R410, dated September 29, 1951, investigates radio listening and attitudes among young people from East Germany. Particularly useful for studying youth political socialization, media consumption, propaganda, and cultural experiences during the early Cold War. The collection provides historical survey reports, although access to underlying individual-level data may vary."
    },
    {
      "title": "GESIS Historical Survey Data Collection: German Public Opinion, 1949–1955",
      "url_or_doi": "https://dbk.gesis.org/dbksearch/",
      "justification": "GESIS maintains a searchable archive of historical German social science datasets, including surveys from the early 1950s. Its collections include studies conducted during the Allied occupation and early Cold War, such as the USIA surveys of Berlin youth. Researchers can identify additional datasets addressing education, political attitudes, social conditions, and demographic characteristics. This is a broader dataset discovery portal rather than a single Berlin-specific dataset."
    },
    {
      "title": "Berlin Historical Statistics: Population and Urban Development, 1950–1961",
      "url_or_doi": "https://berlingeschichte.de/bms/bmstxt01/0103doka.htm",
      "justification": "Historical statistical resource containing Berlin population and urban development information, including statistics from 1950, 1960, and 1961. It draws on historical statistical yearbooks and administrative records from East and West Berlin. Useful for establishing demographic context for youth research, examining population changes, and identifying official statistical sources. It is a compilation of historical statistics rather than an individual-level youth survey."
    },
    {
      "title": "100 Years of Greater Berlin: Historical Demographic and Educational Statistics",
      "url_or_doi": "https://www.statistischebibliothek.de/mir/servlets/MCRFileNodeServlet/BBMonografie_derivate_00000068/100jahregrossberlin.pdf",
      "justification": "Historical statistical publication covering Berlin's demographic, social, and educational development over a century. It contains quantitative historical series relevant to children and young people, including school enrollment trends during the 1950s. Particularly useful for investigating education, demographic changes, and differences between East and West Berlin. The publication provides aggregated historical statistics rather than individual-level records."
    },
    {
      "title": "Youth Migration from East Germany: Historical Statistics for 1958–1960",
      "url_or_doi": "https://germanhistorydocs.org/de/die-besatzungszeit-und-die-entstehung-zweier-staaten-1945-1961/republikflucht-von-jugendlichen-sowie-jugendliche-rueckkehrer-und-zuziehende-in-der-zeit-vom-januar-bis-september-1960-10-november-1960",
      "justification": "Digitized historical document containing quantitative information about young people leaving East Germany, returning, or relocating during the late 1950s and 1960. It includes comparative figures for 1958 and 1959 and geographically differentiated information relevant to Berlin. Useful for researching youth migration, political dissatisfaction, and demographic changes before the construction of the Berlin Wall. The source is a historical statistical document rather than a downloadable microdata dataset."
    }
  ]
}
